12	function hexFromSeed(seed: string, salt: string, len: number): string {
13	  // FNV-1a derived hex — same source style as harness/src/trialState.ts so
14	  // GitHub task seeds remain reproducible.
15	  let h = 2166136261;
16	  const s = seed + ':' + salt;
17	  for (let i = 0; i < s.length; i++) {
18	    h ^= s.charCodeAt(i);
19	    h = Math.imul(h, 16777619);
