22	  while (out.length < len) {
23	    h = Math.imul(h ^ (h >>> 13), 0x5bd1e995);
24	    h = (h + 0x9e3779b9) >>> 0;
25	    out += h.toString(16).padStart(8, '0');
26	  }
27	  return out.slice(0, len);
28	}
