401	async function fetchJson(host: string, token: string, path: string): Promise<unknown> {
402	  const res = await fetch(`https://${host}${path}`, {
403	    headers: ghHeaders(token),
404	  });
405	  if (!res.ok) throw new Error(`GET ${path} -> ${res.status}: ${await res.text()}`);
406	  return res.json();
407	}
408	
409	async function postJson(host: string, token: string, path: string, body: unknown): Promise<unknown> {
410	  const res = await fetch(`https://${host}${path}`, {
411	    method: 'POST',
412	    headers: ghHeaders(token),
413	    body: JSON.stringify(body),
414	  });
415	  if (!res.ok) throw new Error(`POST ${path} -> ${res.status}: ${await res.text()}`);
416	  return res.json();
417	}
418	
419	async function putJson(host: string, token: string, path: string, body: unknown): Promise<unknown> {
420	  const res = await fetch(`https://${host}${path}`, {
421	    method: 'PUT',
422	    headers: ghHeaders(token),
423	    body: JSON.stringify(body),
424	  });
425	  if (!res.ok) throw new Error(`PUT ${path} -> ${res.status}: ${await res.text()}`);
426	  return res.json();
427	}
428	
429	function ghHeaders(token: string): Record<string, string> {
430	  return {
431	    Authorization: `Bearer ${token}`,
432	    Accept: 'application/vnd.github+json',
433	    'X-GitHub-Api-Version': '2022-11-28',
434	    'Content-Type': 'application/json',
435	    'User-Agent': 'cli-vs-mcp-harness/1.0',
436	  };
437	}
